python3 scripts/sheet.py review/sheet_mm9_vs_ours_clips.png 8 260 $M/stand_02.png:MM9_stand $S/sta_Standing_02.png:ours $M/walk_01.png:MM9_walk $S/sta_Walking_01.png:ours $M/run_01.png:MM9_run $S/sta_Running_01.png:ours $M/Hattack1_02.png:MM9_melee $S/sta_AttackMelee_02.png:ours $M/castspell1_03.png:MM9_cast1 $S/sta_AttackRanged_03.png:ours $M/castspell3_03.png:MM9_cast3 $S/sta_AttackRanged3_03.png:ours $M/wince1_02.png:MM9_hit $S/sta_Hit_02.png:ours $M/die1_02.png:MM9_death $S/sta_Death_02.png:ours $M/die1_05.png:MM9_dead $S/sta_Death_05.png:ours $M/pray_02.png:MM9_pray $S/sta_Pray_02.png:ours $M/cower_02.png:MM9_cower $S/sta_Cower_02.png:ours $M/fidget1_03.png:MM9_fidget $S/sta_Fidget_03.png:ours
python3 scripts/sheet.py review/sheet_tiers.png 3 560 $S/ta_f.png $S/tb_f.png $S/tc_f.png $S/ta_q.png $S/tb_q.png $S/tc_q.png $S/ta_b.png $S/tb_b.png $S/tc_b.png
A="Standing Walking Running Backpedal BackpedalRun Fidget Fidget2 Aware Taunt AttackMelee AttackRanged AttackRanged2"; B="AttackRanged3 Hit Hit2 Death Death2 Dead Pray CowerStart Cower CowerEnd Play"; C="HoeWait Hoe HoeFidget SweepWait Sweep SweepFidget HammerWait Hammer HammerFidget WashWait Wash WashFidget"
for t in a b c; do python3 scripts/strip_sheet.py st$t review/strips_${t}_1.png 300 6 $A; python3 scripts/strip_sheet.py st$t review/strips_${t}_2.png 300 6 $B; python3 scripts/strip_sheet.py st$t review/strips_${t}_3.png 300 6 $C
(cd $S; python3 ../../scripts/sheet.py ../sheet_joints_${t}.png 7 300 ${t}pr0.png:waist_Pray ${t}pr1.png:kneeL ${t}pr2.png:kneeR ${t}pr3.png:armpitR ${t}pr4.png:armpitL ${t}pr5.png:elbow ${t}pr6.png:neck ${t}co0.png:waist_Cower ${t}co1.png:armpit ${t}co2.png:elbow ${t}co3.png:neck ${t}ra0.png:hemRun ${t}ra1.png:hemRun ${t}ra2.png:waistRun ${t}ar0.png:armpitAR3 ${t}ar1.png:armpit ${t}ar2.png:elbow ${t}ar3.png:neck ${t}de0.png:waistDeath ${t}de1.png:armpit ${t}de2.png:armpit ${t}de3.png:elbow ${t}de4.png:neck ${t}dd0.png:hemDead ${t}dd1.png:hem ${t}dd2.png:foot ${t}dd3.png:waistDead ${t}dd4.png:armpit ${t}dd5.png:armpit ${t}dd6.png:neck ${t}st0.png:headSt ${t}st1.png:head ${t}st2.png:head ${t}st3.png:hand ${t}st4.png:hand ${t}st5.png:elbow ${t}st6.png:armpit)
